window.kbPageData["views/entry/k-d1f79b0e13f1817a"] = {"key":"entry/k-d1f79b0e13f1817a","state":{"route":"entry/k-d1f79b0e13f1817a"},"node":{"id":"k-d1f79b0e13f1817a","mode":"k","title":"立方体的三面视角与相对面","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["立方体任一三面视角恰见每组相对面中的一面"],"qs":["江苏 2023 A类 行测#90"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"立方体有三组相对面。从同一角度同时看到三个面时，每组恰好可见一面。从每组各选一面，选出的三个面必交于同一顶点，可从该顶点一侧同时看到。","review":{"definition":"立方体有三组相对面。从同一角度同时看到三个面时，每组恰好可见一面。从每组各选一面，选出的三个面必交于同一顶点，可从该顶点一侧同时看到。","explanation":"若每组相对面都能选出一个没有圆的面，这三个面就构成一个看不到圆的三面视角。若至少有一组相对面都画有圆，任一三面视角都会看到其中一个圆。A 项展开图横排从左数第一格和第三格折叠后相对，两格都画有圆，因此选 A。","references":[],"evidence":"当能同时看到3个面时，相对面能且只能出现一个","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 A类 行测#90":{"paper":"江苏 2023 A类 行测","n":90,"mod":"判断推理","src":["22304fe4c340e19d7902.pdf",19],"asrc":["be17f9afe070cf13a0fb.pdf",27],"card":"803bc61f0efb37db1509b703","links":[{"id":"k-d1f79b0e13f1817a","role":"解题依据","why":"任取每组相对面中的一面可组成一个三面视角，因此只有圆形占满至少一组相对面才能保证所有三面视角都有圆。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-d1f79b0e13f1817a":[["江苏 2023 A类 行测#90"]]}};
